+            params: o.func.params,
+            body: o.func.body,
+            generator: o.func.generator,
+            is_async: o.func.is_async,
+            memo_slots_used: o.func.memo_slots_used,
+            memo_blocks: o.func.memo_blocks,
+            memo_values: o.func.memo_values,
