+    Ok(CodegenFunction {
+        loc: codegen_result.loc,
+        id: codegen_result.id,
+        name_hint: codegen_result.name_hint,
+        params: codegen_result.params,
+        body: codegen_result.body,
+        generator: codegen_result.generator,
