+        // Check for eslint-disable (block start)
+        if has_rules {
+            if let Some(names) = rule_names {
+                if matches_eslint_disable(&data.value, names) {
+                    disable_comment = Some(data.clone());
+                    source = Some(SuppressionSource::Eslint);
+                }
+            }
+        }
