+            existing.node_types.insert(node_type);
+        } else {
+            let mut node_types = HashSet::new();
+            node_types.insert(node_type);
+            locations.insert(
+                key.clone(),
+                ImportantLocation {
+                    key,
+                    loc: loc.clone(),
+                    node_types,
+                },
+            );
+        }
+    }
