+fn collect_original_block(
+    stmts: &[Statement],
+    in_single_return_arrow: bool,
+    locations: &mut HashMap<String, ImportantLocation>,
+) {
+    for stmt in stmts {
+        collect_original_statement(stmt, in_single_return_arrow, locations);
